filter.template:
{%- set BI = {'day': 'mdi:white-balance-sunny', 'cosy': 'mdi:sofa', 'night': 'mdi:weather-night'} -%}
{%- set BW = {'day': 'Sat/Sun', 'cosy': 'Fri/Sat', 'night': 'Fri/Sat'} -%}
{%- set BOX = {'margin': '0 6px 6px', 'border': 'var(--ha-card-border-width, 1px) solid var(--ha-card-border-color, var(--divider-color, #e0e0e0))'} -%}
{%- set lamps = ((label_entities('house_schedule') + label_entities('on_off') + ((label_devices('house_schedule') + label_devices('on_off')) | map('device_entities') | sum(start=[]))) | select('match', '(light|switch)\.') | unique | list) -%}
{%- macro lamps_of(scope, b) -%}
  {%- set ns = namespace(l=[]) -%}
  {%- for L in lamps if (scope == 'house' or area_id(L) == scope) and states['switch.ls_lamp_' ~ L.split('.')[1] ~ '_' ~ b ~ '_override'] is not none -%}
    {%- set ns.l = ns.l + [L] -%}
  {%- endfor -%}
  {{- ns.l | sort | to_json -}}
{%- endmacro -%}
{%- macro button(scope, b) -%}
  {%- set ls = lamps_of(scope, b) | from_json -%}
  {%- set n = ls | map('regex_replace', '^(light|switch)\.(.*)$', 'switch.ls_lamp_\\2_' ~ b ~ '_override') | select('is_state', 'on') | list | count -%}
  {{- {'type': 'custom:mushroom-template-card', 'primary': 'Lamps…', 'secondary': ((n ~ ' of ' ~ (ls | count) ~ ' own light') if n else ((ls | count) ~ ' lamps')), 'icon': 'mdi:lightbulb-group', 'icon_color': ('amber' if n else 'grey'), 'color': ('amber' if n else 'grey'), 'tap_action': {'action': 'navigate', 'navigation_path': '#lamps-' ~ scope ~ '-' ~ b}} | to_json -}}
{%- endmacro -%}
{%- macro popup(scope, b) -%}
  {%- set ls = lamps_of(scope, b) | from_json -%}
  {%- set title = ('House' if scope == 'house' else area_name(scope)) ~ ' · ' ~ (b | capitalize) ~ ' Lamps' -%}
  {%- set ns = namespace(c=[]) -%}
  {%- for L in ls -%}
    {%- set o = L.split('.')[1] -%}
    {%- set sw = 'switch.ls_lamp_' ~ o ~ '_' ~ b ~ '_override' -%}
    {%- set nm = ((area_name(area_id(L)) ~ ' · ') if scope == 'house' else '') ~ state_attr(L, 'friendly_name') -%}
    {%- set ns.c = ns.c + [{'type': 'custom:vertical-stack-in-card', 'styles': BOX, 'cards': [
      {'type': 'tile', 'entity': sw, 'name': nm, 'icon': 'mdi:lightbulb-outline', 'color': 'amber', 'hide_state': True, 'tap_action': {'action': 'toggle'}, 'icon_tap_action': {'action': 'toggle'}},
      {'type': 'conditional', 'conditions': [{'condition': 'state', 'entity': sw, 'state': 'on'}], 'card': {'type': 'tile', 'entity': 'light.ls_lamp_' ~ o ~ '_' ~ b, 'name': (b | capitalize) ~ ' Light', 'icon': BI[b], 'state_content': ['brightness', 'color_temp_kelvin'], 'tap_action': {'action': 'more-info'}, 'icon_tap_action': {'action': 'more-info'}}}
    ]}] -%}
  {%- endfor -%}
  {%- if not ls -%}{%- set ns.c = ns.c + [{'type': 'markdown', 'content': 'No lamps with per-lamp settings in this room yet.'}] -%}{%- endif -%}
  {{- {'type': 'custom:bubble-card', 'card_type': 'pop-up', 'hash': '#lamps-' ~ scope ~ '-' ~ b, 'name': title, 'icon': BI[b], 'cards': ns.c} | to_json -}}
{%- endmacro -%}
{%- set out = namespace(p=[]) -%}{%- for b in ['day','cosy','night'] -%}{%- set out.p = out.p + [popup('house', b) | from_json] -%}{%- endfor -%}{{- out.p -}}

