  {{- {'type': 'custom:bubble-card', 'card_type': 'pop-up', 'hash': '#lamps-' ~ scope ~ '-' ~ b, 'name': title, 'icon': BI[b], 'cards': ns.c} | to_json -}}
{%- endmacro -%}
{%- set rooms_all = lamps | map('area_id') | select | unique | list -%}
{%- set ro = namespace(l=[]) -%}
{%- for f in floors() | sort -%}{%- set ro.l = ro.l + (floor_areas(f) | select('in', rooms_all) | sort | list) -%}{%- endfor -%}
{%- set ro.l = ro.l + (rooms_all | reject('in', ro.l) | sort | list) -%}
{%- set rooms = ro.l | select('in', states.input_boolean | map(attribute='object_id') | map('regex_replace', '^ls_(.*)_day_own_light$', '\\1') | list) | list -%}
{%- set out = namespace(c=[], p=[]) -%}
{%- for a in rooms[0::2] -%}
  {%- set bc = namespace(c=[]) -%}
  {%- for b in ['day', 'cosy', 'night'] -%}
    {%- set ol = 'input_boolean.ls_' ~ a ~ '_' ~ b ~ '_own_light' -%}
    {%- set ot = 'input_boolean.ls_' ~ a ~ '_' ~ b ~ '_own_timing' -%}
    {%- set btn = button(a, b) | from_json -%}
    {%- set bc.c = bc.c + [{'type': 'custom:vertical-stack-in-card', 'cards': [
      {'type': 'custom:vertical-stack-in-card', 'styles': {'padding': '5px'}, 'cards': [{'type': 'heading', 'heading': b | capitalize, 'heading_style': 'title', 'icon': BI[b], 'entities': [
        {'entity': ol, 'name': 'Override Light', 'icon': 'mdi:lightbulb-on-outline', 'show_icon': True, 'show_state': True, 'state_content': 'name', 'color': 'amber', 'tap_action': {'action': 'toggle'}},
        {'entity': ot, 'name': 'Override Time', 'icon': 'mdi:clock-edit-outline', 'show_icon': True, 'show_state': True, 'state_content': 'name', 'color': 'amber', 'tap_action': {'action': 'toggle'}}]}]},
      {'type': 'conditional', 'conditions': [{'condition': 'state', 'entity': ol, 'state': 'on'}], 'card': {'type': 'grid', 'columns': 2, 'square': False, 'cards': [
        {'type': 'tile', 'entity': 'light.ls_' ~ a ~ '_' ~ b, 'name': (b | capitalize) ~ ' Light', 'icon': BI[b], 'state_content': ['brightness', 'color_temp_kelvin'], 'tap_action': {'action': 'more-info'}, 'icon_tap_action': {'action': 'more-info'}}, btn]}},
      {'type': 'conditional', 'conditions': [{'condition': 'state', 'entity': ot, 'state': 'on'}], 'card': {'type': 'custom:vertical-stack-in-card', 'cards': [
        {'type': 'tile', 'entity': 'input_number.ls_' ~ a ~ '_' ~ b ~ '_fade', 'name': 'Transition', 'icon': 'mdi:transition', 'features': [{'type': 'numeric-input', 'style': 'buttons'}], 'features_position': 'inline'},
        {'type': 'custom:vertical-stack-in-card', 'styles': {'padding': '5px'}, 'cards': [{'type': 'heading', 'heading': 'Start', 'heading_style': 'subtitle', 'icon': 'mdi:clock-start'}]},
        {'type': 'custom:vertical-stack-in-card', 'horizontal': True, 'styles': dict(BOX, height='auto'), 'cards': [
          {'type': 'tile', 'entity': 'input_datetime.ls_' ~ a ~ '_' ~ b ~ '_start', 'name': 'Week', 'tap_action': {'action': 'more-info'}},
          {'type': 'tile', 'entity': 'input_datetime.ls_' ~ a ~ '_' ~ b ~ '_weekend', 'name': BW[b], 'tap_action': {'action': 'more-info'}}]}]}}]}] -%}
    {%- set out.p = out.p + [popup(a, b) | from_json] -%}
  {%- endfor -%}
  {%- set out.c = out.c + [{'type': 'custom:vertical-stack-in-card', 'title': area_name(a), 'styles': BOX, 'cards': bc.c}] -%}
{%- endfor -%}
{{- out.c + out.p -}}

